"""Capture an actual offline Elf Scout battle before/after the HG33 action atlas."""
from __future__ import annotations
import hashlib,json,os,subprocess
from pathlib import Path
from playwright.sync_api import sync_playwright
ROOT=Path(__file__).parent;GAME=ROOT/'Play-Heoofgaia-HG11.html';SIZES=[(1280,720),(960,540)]
checks=[];screens=[];errors=[]
def sha(p:Path):return hashlib.sha256(p.read_bytes()).hexdigest().upper()
with sync_playwright() as pw:
 launch={'headless':True,'args':['--no-sandbox','--disable-dev-shm-usage','--allow-file-access-from-files']}
 if os.environ.get('HOG_CHROME_PATH'):launch['executable_path']=os.environ['HOG_CHROME_PATH']
 browser=pw.chromium.launch(**launch)
 for width,height in SIZES:
  page=browser.new_page(viewport={'width':width,'height':height},device_scale_factor=1);page.set_default_timeout(10000)
  page.on('pageerror',lambda e:errors.append(str(e)));page.on('console',lambda m:errors.append(m.text) if m.type=='error' else None)
  page.goto(GAME.as_uri(),wait_until='load');page.locator('[data-action="race"][data-race="elf"]').click();page.locator('[data-action="start"]').click()
  setup=page.evaluate("""() => {const E=HOG_ENGINE,s=HOG_APP_DEBUG.getState(),img=document.getElementById('unit-elf-scout'),atlas=HOG_HG33_TROOP_ATLASES?.units?.elf_2;s.army.elf_2=16;E.setFormation(s,[{unitId:'elf_2',count:16}]);const target=E.TILES.find(t=>t.kind==='npc'&&t.value==='Azrael');if(!target)throw Error('Azrael target missing');E.startMarch(s,target.key);E.tick(s,s.lastTick+s.march.remaining/s.speed*1000+1000);HOG_APP_DEBUG.render();return {image:{complete:!!img?.complete,width:img?.naturalWidth,height:img?.naturalHeight,offline:!!img?.src?.startsWith('data:image/webp;base64,')},atlas:!!atlas&&['idle','walk','attack','hit','death'].every(a=>atlas.actions[a]?.count===8),battle:!!s.battle,target:target.key,unit:s.battle?.allies.some(u=>u.unitId==='elf_2'),saveValid:E.strictSave(s)};}""")
  assert setup['image']['complete'] and setup['image']['width']==512 and setup['image']['height']==512 and setup['image']['offline'],{k:v for k,v in setup.items() if k!='state'}
  assert setup['battle'] and setup['unit'] and setup['saveValid'],f'{width}x{height} did not enter a valid actual Elf Scout encounter: {setup}'
  assert setup['atlas'],f'{width}x{height} Elf Scout lacks its offline eight-frame five-action atlas: {setup}'
  assert page.locator('#battle-canvas').is_visible()
  folder=ROOT/'docs'/'evidence'/'hg33'/'H2-elf-scout';before=folder/'before'/f'{width}x{height}.png';after=folder/'after'/f'{width}x{height}.png';before.parent.mkdir(parents=True,exist_ok=True);after.parent.mkdir(parents=True,exist_ok=True)
  page.evaluate("""() => {window.__hg33ElfAtlas=window.HOG_HG33_TROOP_ATLASES;window.__hg33ElfState=JSON.stringify(HOG_ENGINE.clone(HOG_APP_DEBUG.getState()));window.HOG_HG33_TROOP_ATLASES=null;HOG_APP_DEBUG.render()}""");page.wait_for_timeout(160);page.screenshot(path=str(before),animations='disabled')
  beforePaint=page.evaluate("""()=>{const E=HOG_ENGINE,P=HOG_PAINTER,s=HOG_APP_DEBUG.getState(),c=document.getElementById('battle-canvas'),ctx=c.getContext('2d'),calls=[],original=ctx.drawImage;ctx.drawImage=function(img,...a){if(img?.id==='unit-elf-scout'||img?.id==='unit-hg33-elf-2-atlas')calls.push(img.id);return original.call(this,img,...a)};try{P.drawBattle(c,E,s,performance.now(),{showGrid:true});return {calls,stateUnchanged:window.__hg33ElfState===JSON.stringify(E.clone(s)),saveValid:E.strictSave(s)}}finally{ctx.drawImage=original}}""")
  assert beforePaint['calls'].count('unit-elf-scout')>=1 and 'unit-hg33-elf-2-atlas' not in beforePaint['calls'] and beforePaint['stateUnchanged'] and beforePaint['saveValid'],f'{width}x{height} preserved Elf Scout fallback did not draw cleanly: {beforePaint}'
  page.evaluate("""() => {window.HOG_HG33_TROOP_ATLASES=window.__hg33ElfAtlas;delete window.__hg33ElfAtlas;HOG_APP_DEBUG.render()}""");page.wait_for_function("()=>{const e=document.getElementById('unit-elf-scout');return e.complete&&e.naturalWidth===512}")
  paint=page.evaluate("""()=>{const E=HOG_ENGINE,P=HOG_PAINTER,s=HOG_APP_DEBUG.getState(),c=document.getElementById('battle-canvas'),ctx=c.getContext('2d'),calls=[],original=ctx.drawImage,state=JSON.stringify(E.clone(s));ctx.drawImage=function(img,...a){if(img?.id==='unit-elf-scout'||img?.id==='unit-hg33-elf-2-atlas')calls.push(img.id);return original.call(this,img,...a)};try{P.drawBattle(c,E,s,performance.now(),{showGrid:true});const layout=P.battleUnitLayout(s.battle,P.battleProjection(c,E),c.width,c.height),elf=layout.find(e=>e.u.unitId==='elf_2');return {calls,stateUnchanged:state===JSON.stringify(E.clone(s)),saveValid:E.strictSave(s),spriteSize:elf?.size,labelNoOverlap:!!elf&&!P.battleRectOverlap(elf.label,elf.sprite,1)&&!P.battleRectOverlap(elf.label,elf.countBox,1)&&!layout.some(o=>o!==elf&&P.battleRectOverlap(elf.label,o.sprite,1))}}finally{ctx.drawImage=original}}""")
  assert paint['calls'].count('unit-hg33-elf-2-atlas')>=1 and 'unit-elf-scout' not in paint['calls'] and paint['stateUnchanged'] and paint['saveValid'] and paint['labelNoOverlap'],f'{width} Elf Scout atlas not drawn or battle Save changed: {paint}'
  page.wait_for_timeout(100);page.screenshot(path=str(after),animations='disabled')
  checks.extend([{'viewport':f'{width}x{height}','check':'preserved 512px RGBA-derived Elf Scout source and authored 8x5 atlas decode offline','pass':setup['image']['complete'] and setup['atlas']},{'viewport':f'{width}x{height}','check':'real engine march enters valid Elf Scout vs Azrael encounter; Save v07 remains strict','pass':True,'target':setup['target']},{'viewport':f'{width}x{height}','check':'before preserved-master fallback and after atlas screenshots captured','pass':True},{'viewport':f'{width}x{height}','check':'BEFORE draws preserved Elf Scout master and AFTER draws the new atlas; battle state stays unchanged','pass':beforePaint['stateUnchanged'] and paint['calls'].count('unit-hg33-elf-2-atlas')>=1,'fallbackDrawCalls':beforePaint['calls'].count('unit-elf-scout'),'atlasDrawCalls':paint['calls'].count('unit-hg33-elf-2-atlas')}])
  screens.extend([{'state':'before-preserved-master-fallback','viewport':f'{width}x{height}','path':before.relative_to(ROOT).as_posix(),'sha256':sha(before)},{'state':'after-hg33-action-atlas','viewport':f'{width}x{height}','path':after.relative_to(ROOT).as_posix(),'sha256':sha(after)}]);page.close()
 browser.close()
receipt={'sourceCommit':subprocess.check_output(['git','rev-parse','HEAD'],cwd=ROOT,text=True).strip(),'html':GAME.name,'htmlSha256':sha(GAME),'browser':'Playwright using installed Chrome, local file://; actual Elf New Game selection and engine march into Azrael battle; 16-unit visual fixture (no battle outcome claimed).','checks':checks,'screenshots':screens,'pageErrors':errors,'animation':'Before captures use the preserved 512px fallback master; after captures use the authored eight-frame Idle/Walk/Attack/Hit/Death atlas. This is project-created/replacement art, not a recovered client sprite.','pass':len(checks)==8 and len(screens)==4 and not errors}
qa=ROOT/'docs'/'qa'/'hg33'/'H2-elf-scout-chromium.json';qa.parent.mkdir(parents=True,exist_ok=True);qa.write_text(json.dumps(receipt,ensure_ascii=False,indent=2)+'\n',encoding='utf-8')
print(f"HG33 H2 Elf Scout Chromium: {len(checks)}/8 checks; {len(screens)}/4 screenshots; {len(errors)} browser errors")
print(f"HTML SHA256 {receipt['htmlSha256']} · receipt {qa.relative_to(ROOT).as_posix()}")
if not receipt['pass']:raise SystemExit(1)
